#ifndef FALL_MODEL_H
#define FALL_MODEL_H

/* Wrist fall model: logistic regression on the 9 features of features_v2.py, retrained on WEDA-FALL + SmartFallMM (Meta_wrist),
 * 26 Hz.  Generated by ml/fall-detection-wrist/src/export_final.py -- do not edit.
 * Operating point: mode 'trig', prob threshold 0.671, stillness std 0.08, mean tolerance 0.2.
 * PROVISIONAL: the >=95 % fall-recall target is NOT reachable with the specified stillness-confirm rule on wrist data
 * (see ml/fall-detection-wrist/results/REPORT.md). mode 'trig' = threshold tuned WITHOUT the confirm stage (>=95 % trigger-only
 * recall); the stillness parameters below are NOT validated for wrist data. Not for deployment until that is decided.
 * SmartFallMM (c) SmartFall Group, Texas State University (credit required); WEDA-FALL (Marques et al.); weights only, no raw data. */

#define N_FEATURES 9
/* Feature order (features_v2.py):
 *  0: max_mag
 *  1: min_mag
 *  2: mean_mag
 *  3: std_mag
 *  4: range_mag
 *  5: max_jerk
 *  6: std_mag_post
 *  7: count_low
 *  8: tilt_deg
 */

static const float FALL_MEAN[] = {
    1.7620679f, 0.6452326f, 1.0814933f, 0.2429621f, 1.1168354f, 0.63591045f, 0.22349322f, 0.82844275f, 29.523237f
};
static const float FALL_SCALE[] = {
    0.86705136f, 0.22635219f, 0.13865268f, 0.23508994f, 1.0064259f, 0.65373635f, 0.22640507f, 2.087399f, 31.773247f
};
static const float FALL_COEF[] = {
    1.3807468f, -0.68521184f, 0.058695436f, 0.42587507f, 1.3436435f, 0.67146194f, -2.3662438f, -0.090693474f, 0.561541f
};
static const float FALL_INTERCEPT = -2.828873f;
static const float FALL_PROB_THR = 0.671f;
/* stillness: macros are what fall_features.h reads (its #ifndef defaults are 0.05f / 0.2f) */
#define FALL_STILL_STD_THR   0.08f
#define FALL_STILL_MEAN_TOL  0.2f
static const float STILL_STD_THR = 0.08f;
static const float STILL_MEAN_TOL = 0.2f;
#define CONFIRM_SAMPLES 78
#define WIN_SAMPLES 52
#define STRIDE_SAMPLES 13
#define SAMPLE_RATE_HZ 26

/* ---- rate-dependent constants (samples at SAMPLE_RATE_HZ) ---- */
#define TILT_PRE_SAMPLES       13   /* tilt 'before' mean: samples before the peak (0.5 s) */
#define TILT_POST_SAMPLES      13   /* tilt 'after' mean: last samples of the window (0.5 s) */
#define TILT_FALLBACK_SAMPLES  5    /* tilt 'before' = first N when peak < PRE (10 @52 Hz scaled) */
#define POST_STD_SAMPLES       26   /* std_mag_post: last 1 s of the window */
/* short aliases (spec names) */
#define TILT_PRE       TILT_PRE_SAMPLES
#define TILT_POST      TILT_POST_SAMPLES
#define TILT_FALLBACK  TILT_FALLBACK_SAMPLES
#define POST_STD       POST_STD_SAMPLES

/* ---- IMU ODR for this model ----
 * firmware/fall_imu/imu.c selects LSM6DSXX_DATA_RATE_26HZ from SAMPLE_RATE_HZ == 26 (a header swap is enough);
 * the macros below name that selection explicitly (LSM6DS3TR-C CTRL1_XL ODR_XL[3:0] = 0b0010 = 26 Hz). */
#define MODEL_IMU_ODR_ENUM     LSM6DSXX_DATA_RATE_26HZ
#define MODEL_IMU_ODR_XL_BITS  0x2

#endif
